CREATE TABLE IF NOT EXISTS users (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, name text NOT NULL,
 role text NOT NULL CHECK(role IN ('admin','developer','client')), title text NOT NULL DEFAULT '', password_hash text, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS sessions (token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS invitations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text NOT NULL, name text NOT NULL, role text NOT NULL CHECK(role IN ('admin','developer','client')),title text NOT NULL DEFAULT '',token_hash text UNIQUE NOT NULL,expires_at timestamptz NOT NULL,accepted_at timestamptz,created_by uuid REFERENCES users(id),created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,client_name text NOT NULL,description text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'estimated' CHECK(status IN ('estimated','active','closed')),created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS project_members (project_id uuid REFERENCES projects(id) ON DELETE CASCADE,user_id uuid REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(project_id,user_id));
CREATE TABLE IF NOT EXISTS invitation_projects (invitation_id uuid REFERENCES invitations(id) ON DELETE CASCADE,project_id uuid REFERENCES projects(id) ON DELETE CASCADE,PRIMARY KEY(invitation_id,project_id));
CREATE TABLE IF NOT EXISTS estimates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),number integer GENERATED ALWAYS AS IDENTITY UNIQUE,project_id uuid NOT NULL REFERENCES projects(id),title text NOT NULL,client_email text NOT NULL,currency text NOT NULL DEFAULT 'USD',items jsonb NOT NULL,notes text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','sent','approved')),approval_hash text UNIQUE,approved_by text,approved_at timestamptz,created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tickets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),number integer GENERATED ALWAYS AS IDENTITY UNIQUE,project_id uuid NOT NULL REFERENCES projects(id),title text NOT NULL,description text NOT NULL DEFAULT '',acceptance_criteria text NOT NULL DEFAULT '',links jsonb NOT NULL DEFAULT '[]',status text NOT NULL DEFAULT 'backlog' CHECK(status IN ('backlog','active','in_review','solved','closed')),priority text NOT NULL DEFAULT 'medium' CHECK(priority IN ('low','medium','high')),assignee_id uuid REFERENCES users(id),created_by uuid REFERENCES users(id),updated_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS comments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),ticket_id uuid NOT NULL REFERENCES tickets(id) ON DELETE CASCADE,author_id uuid NOT NULL REFERENCES users(id),body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),ticket_id uuid NOT NULL REFERENCES tickets(id) ON DELETE CASCADE,name text NOT NULL,mime text NOT NULL,size integer NOT NULL CHECK(size <= 5242880),data bytea NOT NULL,created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS history(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,project_id uuid REFERENCES projects(id),ticket_id uuid REFERENCES tickets(id),actor_id uuid REFERENCES users(id),actor_label text,action text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS tickets_project_idx ON tickets(project_id);
CREATE INDEX IF NOT EXISTS history_project_idx ON history(project_id,created_at DESC);
CREATE INDEX IF NOT EXISTS history_ticket_idx ON history(ticket_id,created_at DESC);
CREATE INDEX IF NOT EXISTS comments_ticket_idx ON comments(ticket_id);

ALTER TABLE users ADD COLUMN IF NOT EXISTS deleted_at timestamptz;
